type_pretty:
∀ {α : Type u_1} [inst : Fintype α] [inst_1 : DecidableEq α] [Nontrivial α] (G : SimpleGraph α)
  [inst_3 : DecidableRel G.Adj],
  G.Connected →
    have rad := G.radius.toNat;
    let hasC4 :=
      ∃ a b c d, a ≠ b ∧ a ≠ c ∧ a ≠ d ∧ b ≠ c ∧ b ≠ d ∧ c ≠ d ∧ G.Adj a b ∧ G.Adj b c ∧ G.Adj c d ∧ G.Adj d a;
    have cC4 := if hasC4 then 0 else 1;
    ↑rad + ↑⌊G.l⌋ ^ cC4 ≤ ↑G.path
